        renderComponent(DataTableEmailButton, {
          onclick: column.getToggleSortingHandler()
        }),
      cell: ({ row }) => {
        const emailSnippet = createRawSnippet<[{ email: string }]>(
          (getEmail) => {
            const { email } = getEmail();
            return {
              render: () => `<div class="lowercase">${email}</div>` };
          }
        );
        return renderSnippet(emailSnippet, {
          email: row.original.email
        });
      }
    },
    {
      accessorKey: "amount",
      header: () => {
        const amountHeaderSnippet = createRawSnippet(() => {
          return {
            render: () => `<div class="text-end">Amount</div>` };
        });
        return renderSnippet(amountHeaderSnippet);
      },
      cell: ({ row }) => {
        const formatter = new Intl.NumberFormat("en-US", {
          style: "currency",
          currency: "USD"
        });
        const amountCellSnippet = createRawSnippet<[{ amount: number }]>(
          (getAmount) => {
            const { amount } = getAmount();
            const formatted = formatter.format(amount);
            return {
              render: () => `<div class="text-end font-medium">${formatted}</div>` };
          }
        );
        return renderSnippet(amountCellSnippet, {
          amount: row.original.amount
        });
      }
    },
    {
      id: "actions",
      enableHiding: false,
      cell: ({ row }) =>
        renderComponent(DataTableActions, { id: row.original.id })
    }
  ];
  let pagination = $state<PaginationState>({ pageIndex: 0, pageSize: 10 });
  let sorting = $state<SortingState>([]);
  let columnFilters = $state<ColumnFiltersState>([]);
  let rowSelection = $state<RowSelectionState>({});
  let columnVisibility = $state<VisibilityState>({});
  const table = createSvelteTable({
    get data() {
      return data;
    },
    columns,
    state: {
      get pagination() {
        return pagination;
      },
      get sorting() {
        return sorting;
      },
      get columnVisibility() {
        return columnVisibility;
      },
      get rowSelection() {
        return rowSelection;
      },
      get columnFilters() {
        return columnFilters;
      }
    },
