    31→			if (form.data.parent) pbFormData.append('parent', form.data.parent);
    32→			if (form.data.require_login !== undefined)
    33→				pbFormData.append('require_login', form.data.require_login.toString());
    34→			if (form.data.subscriber_only !== undefined)
    35→				pbFormData.append('subscriber_only', form.data.subscriber_only.toString());
    36→			if (form.data.custom_css) pbFormData.append('custom_css', form.data.custom_css);
    37→
    38→			// Handle file upload
